use super::*;

/// Tombstone every flat record a decomposition has superseded.
///
/// # The union of the two stores is NOT the truth, and this is where that shows
///
/// `bsc graph extract` rewrites `X.rs` into `X--mod.rs` plus children and drops the flat record from
/// the COMMITTED store. The runtime store never hears about it and keeps the predecessor forever.
/// Import both and two records claim one module, which `graph-materialize` refuses outright — *"two
/// records claim module `connector` of crate `data`"* — and the whole build stops. Found by exporting
/// and running the build, not by reading the data.
///
/// MEASURED on the real stores: 152 such pairs, every one exactly one `--mod.rs` and one flat, with no
/// other shape among them. So the rule is narrow and checkable rather than a heuristic.
///
/// TOMBSTONED rather than skipped: the superseded record is imported first and then retired, so its
/// content is in the ledger and one `revert` brings it back. That is the difference between resolving
/// this and quietly dropping the loser.
pub fn supersede_decomposed(conn: &Connection, by: &str) -> Result<Vec<String>, String> {
    let mut claims: std::collections::BTreeMap<(String, String), Vec<String>> = Default::default();
    let mut st = conn
        .prepare("SELECT id, json_extract(json, '$.src') FROM records WHERE tier = 'impl'")
        .map_err(|e| e.to_string())?;
    let rows: Vec<(String, Option<String>)> = st
        .query_map([], |r| Ok((r.get(0)?, r.get(1)?)))
        .map_err(|e| e.to_string())?
        .collect::<Result<_, _>>()
        .map_err(|e| e.to_string())?;
    for (id, src) in rows {
        if let Some(k) = module_path(src.as_deref()) {
            claims.entry(k).or_default().push(id);
        }
    }
    let mut retired = Vec::new();
    for ((krate, rel), ids) in claims {
        if ids.len() != 2 {
            continue;
        }
        let winners: Vec<&String> = ids.iter().filter(|i| i.ends_with("--mod.rs")).collect();
        if winners.len() != 1 {
            continue;
        }
        let winner = winners[0].clone();
        for id in ids.iter().filter(|i| **i != winner) {
            crate::remove(conn, id, by,
                Some(&format!("superseded by `{winner}` — both claimed module `{rel}` of `{krate}`")))?;
            retired.push(id.clone());
        }
    }
    Ok(retired)
}
